function run(input, params, h) {
  const ratings = input.memory || [];
  let rating = null;
  for (const word of h.words(input.text)) {
    h.tick();
    const n = Number(word);
    if (rating === null && Number.isFinite(n) && n >= params.lowest && n <= params.highest) {
      rating = Math.round(n);
    }
  }
  if (rating === null) {
    return { say: "Please give a number from " + params.lowest + " to " + params.highest + ".", memory: ratings };
  }
  const now = ratings.concat([rating]);
  const lines = now.map((r, i) => "Version " + (i + 1) + ": " + "★".repeat(r) + " (" + r + ")");
  return { rating: rating, ratings: now, say: lines.join("\n"), memory: now };
}
